def answer_question(image, question="boy under elephant"):
    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    elephant_patches = image_patch.find("elephant")

    if not boy_patches or not elephant_patches:
        return "No boy or elephant found in the image."

    closest_distance = float('inf')
    best_match = None

    for boy_patch in boy_patches:
        for elephant_patch in elephant_patches:
            dist = distance(boy_patch, elephant_patch)
            if dist < closest_distance:
                closest_distance = dist
                best_match = (boy_patch, elephant_patch)

    if closest_distance < 0:
        return "The boy is under the elephant."
    else:
        return f"The boy is {closest_distance:.2f} pixels away from the elephant."

def distance(patch_a: ImagePatch, patch_b: ImagePatch) -> float:
    left_diff = abs(patch_a.left - patch_b.left)
    lower_diff = abs(patch_a.lower - patch_b.lower)
    right_diff = abs(patch_a.right - patch_b.right)
    upper_diff = abs(patch_a.upper - patch_b.upper)

    return max(left_diff, lower_diff, right_diff, upper_diff)

